import http from 'node:http';

const routes = [];
const route = (method, path, handler) => {
  const pattern = new RegExp('^' + path.replace(/:(\w+)/g, '(?<$1>[^/]+)') + '/?$');
  routes.push({ method, pattern, handler });
};

const send = (res, status, data) => {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
};

route('GET', '/', (req, res) => send(res, 200, { hello: 'world' }));
route('GET', '/users/:id', (req, res, params) => send(res, 200, { id: params.id }));

const server = http.createServer(async (req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost');
  const matches = routes.filter((r) => r.pattern.test(pathname));

  if (matches.length === 0) return send(res, 404, { error: 'Not found' });
  const r = matches.find((m) => m.method === req.method);
  if (!r) {
    res.setHeader('Allow', matches.map((m) => m.method).join(', '));
    return send(res, 405, { error: 'Method not allowed' });
  }
  try {
    await r.handler(req, res, pathname.match(r.pattern).groups);
  } catch (err) {
    console.error(err);
    send(res, 500, { error: 'Internal error' });
  }
});

server.listen(3000);

