// npm i express
import express from 'express';

const app = express();
app.use(express.json());

const users = [{ id: 1, name: 'Ann' }];

app.get('/api/users', (req, res) => {
  const { q } = req.query;
  res.json(q ? users.filter((u) => u.name.includes(q)) : users);
});

app.get('/api/users/:id', (req, res) => {
  const user = users.find((u) => u.id === Number(req.params.id));
  if (!user) return res.status(404).json({ error: 'Not found' });
  res.json(user);
});

app.post('/api/users', (req, res) => {
  const user = { id: users.length + 1, name: req.body.name };
  users.push(user);
  res.status(201).json(user);
});

app.listen(3000, () => console.log('API on :3000'));

import express from 'express';

const app = express();

// 1. timing + logging middleware
app.use((req, res, next) => {
  const start = performance.now();
  res.on('finish', () => {
    console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${(performance.now() - start).toFixed(1)}ms`);
  });
  next();
});

app.use(express.json());

// 2. route-level auth middleware
const requireKey = (req, res, next) => {
  const expected = process.env.API_KEY;
  if (!expected || req.get('x-api-key') !== expected) {      // fail closed when the key is not configured
    return next(Object.assign(new Error('Invalid API key'), { status: 401 }));
  }
  next();
};

app.get('/secret', requireKey, (req, res) => res.json({ ok: true }));
app.get('/boom', () => { throw new Error('unexpected'); });

// 3. 404 then error handler (last)
app.use((req, res) => res.status(404).json({ error: 'Not found' }));
app.use((err, req, res, next) => {
  const status = err.status ?? 500;
  if (status >= 500) console.error(err);
  res.status(status).json({ error: status >= 500 ? 'Internal error' : err.message });
});

app.listen(3000);
